example_item.example_item_data:
% Un enregistrement synthetique dont chaque battement est connu, et un
% detecteur fait de cette verite decalee de 20 ms : l'accord est parfait
% apres la periode d'apprentissage.
recording = ecglab.simulate('Seconds', 600, 'Seed', 1);
shift = round(0.02 * recording.rate);
test = recording.annotations.sample + shift;
agreement = ecglab.validate(test, recording.annotations, ...
  'Rate', recording.rate, 'Record', 'synthetic')
